<?php elseif($report):?><section class="card"><h2>Staff Cost Review</h2><form method="get" class="payroll-row"><input type="hidden" name="page" value="costs"><?php p_input('From','start',$start,'date');p_input('To','end',$end,'date');?><button>Review</button></form><dl class="payroll-totals"><div><dt>Approved Staff Cost</dt><dd><?=access_h(p_money($report['staffCost']))?></dd></div><div><dt>Recorded Employee Payments</dt><dd><?=access_h(p_money($report['payments']))?></dd></div><div><dt>Retained Legacy Cost Included Above</dt><dd><?=access_h(p_money($report['legacy_cost']))?></dd></div></dl><p>Payments settle approved liabilities. They do not create another payroll cost. Statutory deductions and employer remittances need separate verification.</p><?php foreach($report['rows'] as $row):?><p><?php p_link($row['approved']['staff_name'].' · '.$row['root']['data']['period'],['id'=>$row['root']['id']]);?> <?=access_h(p_money($row['original_approved']['cost']))?> · Original Approved Cost</p><?php endforeach;if($report['adjustments']['count']):?><h3>Posting-Period Payroll Corrections</h3><p>Cost <?=access_h(p_money($report['adjustments']['cost']))?> · Recorded Payout <?=access_h(p_money($report['adjustments']['paid']))?> · Actual Money Moved By Corrections: GHS 0.00</p><?php foreach($report['adjustment_rows'] as $adjustment):$metadata=json_decode($adjustment['payload'],true,512,JSON_THROW_ON_ERROR);?><p><?php p_link('Payroll #'.$metadata['payroll_id'],['id'=>$metadata['payroll_id']]);?> · <?=access_h(display_date($adjustment['created_at']))?> UTC · Cost <?=access_h(p_money((int)$adjustment['amount_minor']))?> · Payout <?=access_h(p_money((int)$metadata['paid_delta']))?></p><?php endforeach;endif?></section>
